<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {create} from '../api/scenarios';import {create as run} from '../api/runs';import {useAsync} from '../hooks/useAsync';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{go:[string]}>();const name=ref(''),dataset=ref(''),source=ref(''),sink=ref(''),disabled=ref<string[]>([]);const ds=computed(()=>props.data.datasets.find(d=>d.id===dataset.value)||props.data.datasets[0]);const arcs=computed(()=>props.data.arcs.filter(a=>a.dataset_id===ds.value?.id).sort((a,b)=>a.arc_id.localeCompare(b.arc_id)));const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await create({name:name.value,dataset_id:ds.value?.id,source_node:source.value||ds.value?.nodes[0]?.node_id,sink_node:sink.value||ds.value?.nodes[ds.value.nodes.length-1]?.node_id,disabled_arc_ids:disabled.value});name.value='';await props.refresh()})}async function launch(id:string){await execute(async()=>{await run({scenario_id:id});await props.refresh();emit('go','results')})};</script><template><PageHeading code="04 / OUTAGE SCENARIOS" title="锁定同一份边，再比较停用影响。" description="源汇不同且存在。方案保存时冻结每条边的容量与时长；基线和停用结果共用快照。"/><section class="paper" v-if="canWrite"><h2>建立停用对照</h2><form class="grid-form" @submit.prevent="submit"><label>推演名称<input aria-label="推演名称" required minlength="2" v-model="name"/></label><label>网络<select aria-label="推演网络" :value="ds?.id" @change="dataset=($event.target as HTMLSelectElement).value;source='';sink='';disabled=[]"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>源节点<select aria-label="推演源节点" :value="source||ds?.nodes[0]?.node_id" @change="source=($event.target as HTMLSelectElement).value"><option v-for="n in ds?.nodes" :key="n.node_id" :value="n.node_id">{{n.node_id}} · {{n.label}}</option></select></label><label>汇节点<select aria-label="推演汇节点" :value="sink||ds?.nodes[ds.nodes.length-1]?.node_id" @change="sink=($event.target as HTMLSelectElement).value"><option v-for="n in ds?.nodes" :key="n.node_id" :value="n.node_id">{{n.node_id}} · {{n.label}}</option></select></label><fieldset class="wide"><legend>停用边 / 不选即无停用基准</legend><div class="outage-checks"><label v-for="a in arcs" :key="a.id"><input type="checkbox" :value="a.arc_id" v-model="disabled" :aria-label="'停用'+a.arc_id"/><span><b>{{a.arc_id}}</b> {{a.source}}→{{a.target}}<small>{{a.capacity}}箱/小时 · {{a.travel_minutes}}分钟</small></span></label></div></fieldset><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">冻结并保存推演</button></form></section><section class="paper"><h2>已锁定方案</h2><article class="scenario-row" v-for="s in data.scenarios" :key="s.id"><div><span class="eyebrow">{{s.source_node}} → {{s.sink_node}} / {{s.arc_snapshot.length}}条边快照</span><h3>{{s.name}}</h3><p>停用：{{s.disabled_arc_ids.length?s.disabled_arc_ids.join('、'):'无'}}；源网络：{{data.datasets.find(d=>d.id===s.dataset_id)?.name}}</p></div><button class="secondary" v-if="canWrite" :disabled="busy" @click="launch(s.id)">运行韧性对照　→</button></article></section><section class="paper"><h2>运行队列</h2><div class="table-scroll"><table><thead><tr><th>推演</th><th>状态</th><th>时间</th></tr></thead><tbody><tr v-for="r in data.runs" :key="r.id"><td>{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}}</td><td><Status :value="r.status"/></td><td>{{r.created_at.slice(0,19).replace('T',' ')}}</td></tr></tbody></table></div></section></template>
